Absolutely. Here’s a **full working version** of both **Recursive** and **Iterative Quick Sort** in C — using the **first element as the pivot** for both, to keep it consistent and comparable.

---

## ✅ 1. Recursive Quick Sort (Pivot = First Element)

```c
#include <stdio.h>

void swap(int *a, int *b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

int partition(int arr[], int low, int high) {
    int pivot = arr[low]; // First element as pivot
    int i = low + 1;
    int j = high;

    while (1) {
        while (i <= high && arr[i] <= pivot) i++;
        while (j >= low && arr[j] > pivot) j--;

        if (i >= j) break;

        swap(&arr[i], &arr[j]);
    }

    swap(&arr[low], &arr[j]);
    return j;
}

void quickSortRecursive(int arr[], int low, int high) {
    if (low < high) {
        int pivotIndex = partition(arr, low, high);

        quickSortRecursive(arr, low, pivotIndex - 1);   // Left of pivot
        quickSortRecursive(arr, pivotIndex + 1, high);  // Right of pivot
    }
}
```

---

## ✅ 2. Iterative Quick Sort (Pivot = First Element)

```c
void quickSortIterative(int arr[], int low, int high) {
    int stack[high - low + 1];
    int top = -1;

    // Push initial boundaries
    stack[++top] = low;
    stack[++top] = high;

    while (top >= 0) {
        high = stack[top--];
        low = stack[top--];

        int pivotIndex = partition(arr, low, high);

        // Left of pivot
        if (pivotIndex - 1 > low) {
            stack[++top] = low;
            stack[++top] = pivotIndex - 1;
        }

        // Right of pivot
        if (pivotIndex + 1 < high) {
            stack[++top] = pivotIndex + 1;
            stack[++top] = high;
        }
    }
}
```

---

